import math

def smallest_divisor(nums, threshold):
    def compute_sum(divisor):
        return sum(math.ceil(num / divisor) for num in nums)

    lo, hi = 1, max(nums)

    while lo < hi:
        mid = (lo + hi) // 2
        if compute_sum(mid) <= threshold:
            hi = mid
        else:
            lo = mid + 1

    return lo

